//! The contract of Mold: for the same data, the runtime interpreter and the code generated by `#[derive(Mold)]`
//! produce the same bytes. Every case of the shared corpus (`smeltery-mold/tests/corpus/<case>/`) is rendered both
//! ways and compared with its `expected.html`.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]

use smeltery_mold::{Host, Template, Value};
use smeltery_mold_macros::Mold;
use std::collections::BTreeMap;

struct TestHost {
    title_errors: Vec<String>,
}

impl Host for TestHost {
    fn csrf_token(&self) -> Option<&str> {
        Some("tok<&>")
    }
    fn authenticated(&self) -> bool {
        true
    }
    fn errors(&self, field: &str) -> &[String] {
        if field == "title" {
            &self.title_errors
        } else {
            &[]
        }
    }
    fn old(&self, field: &str) -> Option<&str> {
        (field == "title").then_some("Old <title>")
    }
    fn session(&self, key: &str) -> Option<String> {
        (key == "status").then(|| "Saved <ok>".to_owned())
    }
    fn route(&self, name: &str, params: &[(String, String)]) -> Result<String, String> {
        let q: Vec<String> = params.iter().map(|(k, v)| format!("{k}={v}")).collect();
        Ok(if q.is_empty() {
            format!("/{name}")
        } else {
            format!("/{name}?{}", q.join("&"))
        })
    }
    fn spark(&self, name: &str, props: &Value) -> Result<String, String> {
        let json = serde_json::to_string(props).map_err(|e| e.to_string())?;
        Ok(format!("<div data-spark=\"{name}\">{json}</div>"))
    }
    fn sparks_scripts(&self) -> String {
        "<script src=\"/sparks.js\"></script>".to_owned()
    }
    fn alloy_page(&self, id: &str) -> Result<String, String> {
        Ok(format!(
            "<script data-page=\"{id}\" type=\"application/json\">{{\"component\":\"welcome\"}}</script><div id=\"{id}\"></div>"
        ))
    }
    fn alloy_head(&self) -> String {
        "<meta name=\"alloy-head\">".to_owned()
    }
    fn vite(&self, entries: &[&str]) -> Result<String, String> {
        let entries = if entries.is_empty() {
            &["default.js"][..]
        } else {
            entries
        };
        Ok(entries
            .iter()
            .map(|e| format!("<script type=\"module\" src=\"/build/{e}\"></script>"))
            .collect())
    }
}

fn host() -> TestHost {
    TestHost {
        title_errors: vec!["Title is required".to_owned(), "second".to_owned()],
    }
}

fn check<T: Template>(case: &str, t: &T) {
    let expected = std::fs::read_to_string(format!(
        "{}/../smeltery-mold/tests/corpus/{case}/expected.html",
        env!("CARGO_MANIFEST_DIR")
    ))
    .unwrap();
    let h = host();
    let runtime = t
        .render_runtime(&h)
        .unwrap_or_else(|e| panic!("{case} runtime: {e}"));
    let compiled = t
        .render_compiled(&h)
        .unwrap_or_else(|e| panic!("{case} compiled: {e}"));
    assert_eq!(compiled, runtime, "{case}: compiled != runtime");
    assert_eq!(runtime, expected, "{case}: runtime != expected.html");
    assert_eq!(T::NAME, "page");
}

#[derive(Mold)]
#[mold(
    "page",
    crate = "smeltery_mold",
    dir = "../smeltery-mold/tests/corpus/basics/views"
)]
struct Basics {
    title: String,
    html: &'static str,
    unicode: String,
    count: i32,
    flag: bool,
    ratio: f32,
    big_f: f64,
    small_f: f64,
    whole_f: f64,
    huge: u64,
    name: String,
    missing_opt: Option<String>,
    some_opt: Option<String>,
    empty: String,
    tags: Vec<String>,
    scores: BTreeMap<String, i64>,
}

#[test]
fn basics() {
    check(
        "basics",
        &Basics {
            title: "<Hello & 'World'>".into(),
            html: "<em>raw</em>",
            unicode: "héllo wörld ✓".into(),
            count: 5,
            flag: false,
            ratio: 0.1,
            big_f: 1e21,
            small_f: 0.000001,
            whole_f: 3.0,
            huge: u64::MAX,
            name: "Ann".into(),
            missing_opt: None,
            some_opt: Some("yes".into()),
            empty: String::new(),
            tags: vec!["x".into(), "y".into()],
            scores: BTreeMap::from([("math".to_owned(), 9)]),
        },
    );
}

