#[derive(Mold)]
#[mold("errors", crate = "smeltery_mold", dir = "tests/views")]
struct Errors {
    a: i64,
    b: i64,
    items: Vec<i64>,
}

#[test]
fn runtime_errors_match_in_both_modes() {
    let t = Errors {
        a: 1,
        b: 0,
        items: vec![],
    };
    let runtime = t.render_runtime(&smeltery_mold::NoHost).unwrap_err();
    let compiled = t.render_compiled(&smeltery_mold::NoHost).unwrap_err();
    assert_eq!(runtime.to_string(), compiled.to_string());
    assert_eq!(runtime.excerpt, compiled.excerpt);
    assert_eq!(
        compiled.to_string(),
        "tests/views/errors.mold.html:2:6: division by zero"
    );
}

#[test]
fn render_picks_the_build_mode() {
    let t = Request {
        post_id: 1,
        start: 2,
    };
    let h = host();
    assert_eq!(t.render(&h).unwrap(), t.render_compiled(&h).unwrap());
}

