#[derive(Mold)]
#[mold("alloy_off", crate = "smeltery_mold", dir = "tests/views")]
struct AlloyOff {}

#[derive(Mold)]
#[mold("vite_off", crate = "smeltery_mold", dir = "tests/views")]
struct ViteOff {}

/// Without an Alloy host, `@alloy` and `@vite` fail the same way in both modes, at the directive; `@alloyHead`
/// renders nothing.
#[test]
fn alloy_without_a_host_fails_alike_in_both_modes() {
    let off = "Alloy is not enabled: call `.alloy(…)` in bootstrap/app.rs";
    for (runtime, compiled, at) in [
        (
            AlloyOff {}.render_runtime(&smeltery_mold::NoHost),
            AlloyOff {}.render_compiled(&smeltery_mold::NoHost),
            "tests/views/alloy_off.mold.html:3:3",
        ),
        (
            ViteOff {}.render_runtime(&smeltery_mold::NoHost),
            ViteOff {}.render_compiled(&smeltery_mold::NoHost),
            "tests/views/vite_off.mold.html:2:1",
        ),
    ] {
        let (runtime, compiled) = (runtime.unwrap_err(), compiled.unwrap_err());
        assert_eq!(runtime.to_string(), compiled.to_string());
        assert_eq!(runtime.excerpt, compiled.excerpt);
        assert_eq!(compiled.to_string(), format!("{at}: {off}"));
    }
}

