/// `x@endif` stay text in both modes.
#[test]
fn adjacency() {
    check(
        "adjacency",
        &Adjacency {
            show: true,
            name: "Ann".into(),
        },
    );
}

#[derive(serde::Serialize)]
struct JsPost {
    title: String,
    views: u32,
}

#[derive(Mold)]
#[mold(
    "page",
    crate = "smeltery_mold",
    dir = "../smeltery-mold/tests/corpus/js/views"
)]
struct Js {
    name: String,
    id: u64,
    post: JsPost,
    tags: Vec<&'static str>,
    nothing: Option<String>,
    count: i32,
    ratio: f32,
    flag: bool,
    line: String,
    evil_url: String,
    hidden_url: String,
    data_url: String,
    good_url: String,
    rel_url: String,
    mail_url: String,
    colon_path: String,
}

/// The `json` and `url` filters produce the same bytes in both modes (S3-01, S3-09).
#[test]
fn js() {
    check(
        "js",
        &Js {
            name: "'+alert(1)+'\\</script><!--&\"".into(),
            id: 7,
            post: JsPost {
                title: "<b>x</b>".into(),
                views: 3,
            },
            tags: vec!["a", "b"],
            nothing: None,
            count: 5,
            ratio: 0.1,
            flag: true,
            line: "a\u{2028}b\u{2029}c".into(),
            evil_url: "JavaScript:alert(1)".into(),
            hidden_url: " \tjava\nscript:alert(2)".into(),
            data_url: "data:text/html,<script>alert(3)</script>".into(),
            good_url: "https://example.test/?a=1&b=2".into(),
            rel_url: "/posts/1".into(),
            mail_url: "mailto:me@example.test".into(),
            colon_path: "posts/a:b".into(),
        },
    );
}

#[derive(Mold)]
#[mold("safe_field", crate = "smeltery_mold", dir = "tests/views")]
struct SafeField {
    html: smeltery_mold::rt::Safe,
    text: String,
}

/// Slot HTML (`rt::Safe`) is written raw by both modes, also when it reaches a template as a field; plain strings
/// are escaped by both (S3-07: the interpreter used to escape it while compiled code did not).
#[test]
fn safe_values_render_alike_in_both_modes() {
    let t = SafeField {
        html: smeltery_mold::rt::Safe("<b>x</b>".into()),
        text: "<b>x</b>".into(),
    };
    let h = host();
    let runtime = t.render_runtime(&h).unwrap();
    assert_eq!(runtime, t.render_compiled(&h).unwrap());
    assert_eq!(
        runtime,
        "[<b>x</b>] [&lt;b&gt;x&lt;/b&gt;] [\"\\u003cb\\u003ex\\u003c/b\\u003e\"]\n"
    );
}
